  for(var e:world.getEntitiesOfClass(GateWeaponProjectileEntity.class,area))e.discard();Utils.setMode(stack,2);for(int n=0;n<MTConfig.TREASURY_PROJECTION_AOE_COOLDOWN+1;n++)glove.onUseTick(world,p,stack,72000-n);require(!world.getEntitiesOfClass(GateWeaponProjectileEntity.class,area).isEmpty(),"Treasury AOE mode emits native weapons");
