 public static void run(ServerPlayer fixture){var world=fixture.level();var p=DoomIntegration.player(world,"LateFamilies",GameType.SURVIVAL,570);var players=((stepsword.mahoutsukai.checks.mixin.PlayerListAccessor)world.getServer().getPlayerList()).mahoutsukai$playersByUUID();players.put(p.getUUID(),p);try{treasury(p);butterfly(p);mystic(p);scrying(p);}finally{p.stopUsingItem();p.removeAllEffects();players.remove(p.getUUID());p.discard();}}
